import { _decorator, Component, Node } from 'cc';
import { Bus } from '../../Engine/Bus';
import { HallEvents } from '../HallEvents';

const { ccclass } = _decorator;

@ccclass('WorldViewController')
export class WorldViewController extends Component {
    
    private _bus: Bus = null!;
    private _targetNode: Node = null;

    // 缩放限制
    private readonly _minScale = 0.5;
    private readonly _maxScale = 2.0;

    setup(bus: Bus, targetNode: Node) {
        this._bus = bus;
        this._targetNode = targetNode;
        this._registerSceneListeners();
    }

    protected onDestroy(): void {
        this._unregisterSceneListeners();
    }

    private _registerSceneListeners(): void {
        // 监听单指/鼠标拖拽（带增量）
        this._bus.on(HallEvents.INPUT_SINGLE_DRAG, this._onWorldDrag, this);
        // 监听双指/滚轮缩放
        this._bus.on(HallEvents.INPUT_PINCH, this._onWorldPinch, this);
    }

    private _unregisterSceneListeners(): void {
        this._bus.off(HallEvents.INPUT_SINGLE_DRAG, this._onWorldDrag, this);
        this._bus.off(HallEvents.INPUT_PINCH, this._onWorldPinch, this);
    }

    /**
     * 处理地图拖拽
     * @param dx 屏幕X轴增量
     * @param dy 屏幕Y轴增量
     */
    private _onWorldDrag(dx: number, dy: number): void {
        if (!this._targetNode) return;

        const pos = this._targetNode.position;
        const currentScale = this._targetNode.scale.x;

        // 【核心细节】：必须要除以当前的缩放比例，否则地图放大后，拖动会显得很慢（不跟手）
        this._targetNode.setPosition(
            pos.x + dx / currentScale, 
            pos.y + dy / currentScale, 
            pos.z
        );
    }

    /**
     * 处理地图缩放
     * @param factor 缩放系数
     */
    private _onWorldPinch(factor: number): void {
        if (!this._targetNode) return;

        const currentScale = this._targetNode.scale.x;
        let newScale = currentScale * factor;

        // 限制缩放范围
        newScale = Math.max(this._minScale, Math.min(this._maxScale, newScale));

        // 如果超出了限制，不更新
        if (Math.abs(newScale - currentScale) < 0.001) return;

        this._targetNode.setScale(newScale, newScale, 1);
    }
}